#include <string>
#include <unordered_set>

class Solution {
public:
    std::string trimTrailingVowels(std::string s) {
        std::unordered_set<char> vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'};
        int idx = (int)s.length() - 1;
        while (idx >= 0 && vowels.count(s[idx])) idx--;
        return s.substr(0, idx + 1);
    }
};

import java.util.*;

class Solution {
    public String trimTrailingVowels(String s) {
        Set<Character> vowels = new HashSet<>(Arrays.asList('a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'));
        int idx = s.length() - 1;
        while (idx >= 0 && vowels.contains(s.charAt(idx))) idx--;
        return s.substring(0, idx + 1);
    }
}

function trimTrailingVowels(s) {
    const vowels = new Set(['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U']);
    let idx = s.length - 1;
    while (idx >= 0 && vowels.has(s[idx])) idx--;
    return s.slice(0, idx + 1);
}
